#!/bin/bash
set -e

# Fix: idle auto-logout was missing the 30-minute mark for tabs left
# in the background -- browsers throttle setInterval heavily in
# unfocused tabs, so the periodic check alone can't be relied on.
# Now also checks immediately via the Page Visibility API the moment
# a tab becomes visible again, which isn't subject to that throttling.
# Run this from your veda-hmis repo root in Codespaces.

mkdir -p "app/components"
echo "" | base64 -d > "app/components/AppShell.js"
echo "Wrote app/components/AppShell.js"

git add app/components/AppShell.js
git commit -m "Fix idle auto-logout missing timeout in backgrounded tabs (throttled setInterval)"
git push

echo "Done."
